/**
 * Pipedrive Node - Version 2
 * Discriminator: resource=dealProduct, operation=update
 */


interface Credentials {
  pipedriveApi: CredentialReference;
  pipedriveOAuth2Api: CredentialReference;
}

/** Update an activity */
export type PipedriveV2DealProductUpdateParams = {
  resource: 'dealProduct';
  operation: 'update';
  authentication?: 'apiToken' | 'oAuth2' | Expression<string>;
/**
 * ID of the deal whose product to update
 * @default 0
 */
    dealId?: number | Expression<number>;
/**
 * ID of the deal-product (the ID of the product attached to the deal, not the product ID itself)
 * @default 0
 */
    productAttachmentId?: number | Expression<number>;
/**
 * Update Fields
 * @default {}
 */
    updateFields?: {
    /** Text to describe this product-deal attachment
     */
    comments?: string | Expression<string> | PlaceholderValue;
    /** The value of the discount. The discount type can be specified in discount_type.
     * @default 0
     */
    discount?: number | Expression<number>;
    /** The type of the discount
     * @default percentage
     */
    discount_type?: 'percentage' | 'amount' | Expression<string>;
    /** Price at which to update this product in the deal
     * @default 0
     */
    item_price?: number | Expression<number>;
    /** How many items of this product in the deal
     * @default 1
     */
    quantity?: number | Expression<number>;
    /** The tax percentage
     * @default 0
     */
    tax?: number | Expression<number>;
  };
};

export type PipedriveV2DealProductUpdateNode = {
  type: 'n8n-nodes-base.pipedrive';
  version: 2;
  credentials?: Credentials;
  config: NodeConfig<PipedriveV2DealProductUpdateParams>;
};